create extension if not exists "pgcrypto";create table people(id uuid primary key default gen_random_uuid(),name text not null,type text not null,email text,phone text,active boolean default true);create table class_groups(id uuid primary key default gen_random_uuid(),name text not null,start_date date,end_date date,status text not null);create unique index one_active_group on class_groups((status)) where status='ATIVA';create table enrollments(class_id uuid references class_groups,student_id uuid references people,primary key(class_id,student_id));create table recurring_activities(id uuid primary key default gen_random_uuid(),weekday int,start_time time,end_time time,teacher_id uuid references people,title text,active boolean default true);create table lessons(id uuid primary key default gen_random_uuid(),date date,fixed_id uuid references recurring_activities,type text,title text,content text,notes text,teacher_id uuid references people,start_time time,end_time time,done boolean default false);create table attendance(lesson_id uuid references lessons,student_id uuid references people,status text,primary key(lesson_id,student_id));
